def _tip(key: str) -> str:
    """Return tooltip text for st.metric(help=...) and st.column_config help=."""
    return _TIPS.get(key, "")


def _m(val_str: str) -> str:
    """Return masked placeholder when privacy mode is on, otherwise the value as-is."""
    return "••••••" if st.session_state.get("_privacy", True) else val_str


# _tickers_traded_since relocated to stock_analyzer/broker_sync.py 2026-08-24
# (as `tickers_traded_since`, no leading underscore) so the headless cron path
# can compute the same broker-drift verdict without importing this
# Streamlit-laden module. Call sites here now use `broker_sync.tickers_traded_since`.


def _fmt_asof_et(captured_at) -> str:
    """A stored capture time as an ET wall-clock string.

    PostgREST hands `timestamptz` back normalized to UTC, so slicing the
    raw string printed a 14:14 ET capture as "18:14" — a FUTURE time to
    someone reading at 15:00 ET. Everything else on Home is ET.
    """
    try:
        _ts = pd.to_datetime(captured_at, utc=True, errors="coerce",
                             format="ISO8601")
        if _ts is None or pd.isna(_ts):
            return "unknown"
        _et = _ts.tz_convert("America/New_York")
        # Include the YEAR when it isn't the current one, or a year-old
        # snapshot reads as recent (feedback_timestamp_chips).
        _fmt = "%b %d, %H:%M ET" if _et.year == _today_et().year else "%b %d %Y, %H:%M ET"
        return _et.strftime(_fmt)
    except (TypeError, ValueError):
        return "unknown"


def _render_broker_drift(placeholder, verdict) -> None:
    """Render 🏠 Home's app-vs-broker drift banner from a pure verdict.

    All the branching lives in `broker_sync.decide_drift_banner`, which is
    Streamlit-free and fully unit-tested; this function only turns a state into
    words. Deliberately silent when clean and fresh — a green "matches your
    broker" line on every render is the noise that trains a user past the amber
    one, so the clean confirmation stays on 💰 Account where you go to look.

    AWARENESS ONLY, never a gate. A drift check cannot be trusted to be armed
    (it goes quiet exactly when the broker is unreachable), and the false-
    positive surface is broad — multi-account aggregation, instrument kinds,
    settlement lag. Suppressing a buy on a phantom would be a hard failure with
    no recourse; this is a user-fixable data error, so the app routes to the
    fix rather than locking the doors.
    """
    if not verdict:
        return
    state = verdict.get("state")
    if state == "none":
        return

    with placeholder.container():
        if state == "unknown":
            # Silent when no broker is linked at all — there is nothing to be
            # unknown ABOUT, and a permanent caption above Portfolio Value for
            # a feature the user never set up is pure noise.
            try:
                from stock_analyzer import snaptrade_client as _sc
                if not _sc.has_snaptrade():
                    return
            except Exception:
                return
            if verdict.get("reason") == "check_failed":
                st.caption(
                    "⚠️ Broker drift **not checked** — the comparison against your broker didn't "
                    "complete this run, so the app can't confirm Portfolio Value matches your broker."
                )
            else:
                st.caption(
                    "⚠️ Broker drift **not checked** — no broker snapshot available, so "
                    "the app can't confirm Portfolio Value matches your broker."
                )
            return

        _asof = _fmt_asof_et(verdict.get("captured_at"))
        if state == "stale_clean":
            _why = ("not re-checked since" if verdict.get("is_stale")
                    else "some linked accounts didn't respond")
            # "as of unknown" is ungrammatical, and an unreadable capture time
            # is itself why the check counts as stale — say that instead.
            _when = "at the last check" if _asof == "unknown" else f"as of {_asof}"
            st.caption(
                f"ℹ️ No broker mismatch {_when} — {_why}. Not a clean bill of "
                "health for right now."
            )
            return

        if state == "awaiting_sync":
            # Everything that differs is explained by a trade the user logged
            # since the snapshot. They did nothing wrong, so this is a caption,
            # not a warning — and it must never say "missing trade".
            _aw_list = verdict.get("awaiting_sync")
            _aw = ", ".join(_aw_list if isinstance(_aw_list, list) else [])
            st.caption(
                f"ℹ️ Waiting on the broker to catch up on **{_aw}** — you logged a trade "
                f"after the {_asof} broker snapshot, so a difference here is expected. "
                "Nothing to fix."
            )
            return

        # state == "drift"
        _imp   = verdict.get("impact")
        if not isinstance(_imp, dict):
            _imp = {}
        _over  = float(_imp.get("overstated") or 0.0)
        _lines = []
        for _r in _imp.get("priced", []):
            _dir = "extra in app" if _r["shares"] > 0 else "missing from app"
            _lines.append(
                f"- **{_r['ticker']}** — {abs(_r['shares']):g} sh {_dir} "
                f"({_m(f'${abs(_r['dollars']):,.0f}')})"
            )
        for _r in _imp.get("unpriced", []):
            _lines.append(
                f"- **{_r['ticker']}** — {abs(_r['shares']):g} sh mismatch (value unavailable)"
            )
        for _r in _imp.get("rh_only_shares", []):
            _lines.append(
                f"- **{_r['ticker']}** — {_r['shares']:g} sh at your broker, not in your "
                "app; its value is missing from Portfolio Value entirely"
            )

        # Sub-dollar rounding guard, NOT a policy threshold: below $1 the
        # figure is noise and the generic headline reads better. Both
        # branches warn and no gate moves either way.
        if abs(_over) >= 1:
            _word = "overstated" if _over > 0 else "understated"
            _head = f"Portfolio Value may be **{_word} by ~{_m(f'${abs(_over):,.0f}')}**"
        else:
            _head = "Your holdings don't match your broker"

        # ALWAYS dated, not only when stale. The broker side refreshes once a
        # day while the book is diffed live, so an undated "overstated by $X"
        # reads as a claim about right now when it is really a comparison
        # against this morning's capture.
        _stale_note = f"  \n_Broker snapshot as of {_asof}; it refreshes once daily._"
        _partial    = ("  \n_Some linked accounts didn't respond, so there may be more._"
                       if not verdict.get("all_accounts_ok") else "")
        st.warning(
            f"⚠️ **Your book doesn't match your broker** — {_head}\n\n"
            + "\n".join(_lines)
            + "\n\nEvery weight, gate and suggested position size is computed from "
              "Portfolio Value. Most likely a trade logged after that snapshot; "
              "otherwise a missing trade — check 📒 Trade Journal or "
              "💰 Account → Broker Sync (full reconciliation)."
            + _stale_note + _partial
        )


# Shared severity palette for Act Today / Review cards (Home) and the simple
# action cards on the Summary page — one source instead of each renderer
# hardcoding its own hex.
_HOME_URGENT   = "#ef4444"  # red   — Act Today bucket / critical priority
_HOME_ELEVATED = "#f59e0b"  # amber — active ACT directive / medium priority
_HOME_CALM     = "#94a3b8"  # grey  — Watch / monitoring, no action needed
_HOME_GAIN     = "#00C851"  # green — matches the Home live price strip
_HOME_LOSS     = "#ff4444"  # red   — matches the Home live price strip


def _render_sparkline(values: list[float], color: str, key: str) -> None:
    """Tiny inline trend line (no axes/gridlines/legend) under a KPI tile.
    `values` chronological, oldest first. No-ops below 2 points."""
    if not values or len(values) < 2:
        return
    _fig = go.Figure(go.Scatter(y=values, mode="lines",
                                 line=dict(color=color, width=1.6), hoverinfo="skip"))
    _fig.update_layout(
        height=36, margin=dict(l=0, r=0, t=2, b=2),
        xaxis=dict(visible=False), yaxis=dict(visible=False), showlegend=False,
        plot_bgcolor="rgba(0,0,0,0)", paper_bgcolor="rgba(0,0,0,0)",
    )
    st.plotly_chart(_fig, width="stretch", config={"displayModeBar": False}, key=key)


def _debate_verdict_icon(verdict: str | None, debate_type: str) -> str:
    """Verdict icon + label text for a debate's expander title — must be
    computed BEFORE the expander opens (Streamlit needs the title string up
    front), so this is deliberately separate from body rendering
    (_render_debate_result below). Hoisted module-level (not a closure) since
    Streamlit only executes the matching page branch per rerun — this is
    called from Home's Grow Today/Act Today cards AND 🧠 AI Insights' Debate
    Log tab (Multi-Agent Debate Phase 3).

    debate_type: "entry" or "exit" — selects label wording only ("Bull
    wins"/"Bear wins" vs "Hold defensible"/"Exit supported"); the same
    verdict values (bull_wins/bear_wins/contested/None) drive both.
    """
    if debate_type == "exit":
        return (
            "🟢 Hold defensible" if verdict == "bull_wins" else
            "🔴 Exit supported"  if verdict == "bear_wins" else
            "⚖️ Contested"        if verdict == "contested" else
            "⚠️ Error"
        )
    return (
        "🟢 Bull wins" if verdict == "bull_wins" else
        "🔴 Bear wins" if verdict == "bear_wins" else
        "⚖️ Contested"  if verdict == "contested" else
        "⚠️ Error"
    )


def _render_debate_result(row: dict, debate_type: str) -> None:
    """Render one stored debate's body: exit-only calm-advisor disclaimer,
    scores, key dispute, grounded warning, and full transcript. Shared by the
    entry-debate cache-hit render, the exit-debate cache-hit render, and the
    🧠 AI Insights Debate Log tab (Multi-Agent Debate Phase 3) — extracted here
    so the same markup doesn't exist a third time. Caller is responsible for
    the expander itself and its title (use _debate_verdict_icon() for that,
    computed first — see docs/plans/multi-agent-debate-phase3.md).

    row: a debate_cache row (dict) with verdict/key_dispute/bull_case_score/
         bear_case_score/grounded/transcript keys — as returned by
         db.load_debate_cache() or db.load_all_debates().
    debate_type: "entry" or "exit" — selects label wording (score-column
         labels) AND whether the exit-only disclaimer renders.
    """
    _v   = row.get("verdict")
    _err = row.get("error")
    _kd  = row.get("key_dispute")
    _bsc = row.get("bull_case_score")
    _brc = row.get("bear_case_score")
    _grd = row.get("grounded")
    _trn = row.get("transcript") or []
    # _failed covers two distinct states: total API failure (no transcript at
    # all) and judge-call failure (transcript present but verdict is None with
    # error=="judge_failed"). Both need an explicit message so the user can
    # distinguish an infra hiccup from a genuine 50/50 contested result.
    _failed = (_v is None and not _trn) or _err == "judge_failed"

    if debate_type == "exit":
        _bull_label, _bear_label = "Hold case", "Exit case"
        st.caption(
            "This debate challenges the exit signal — it does not change "
            "it. The recommendation stands; this is a structured second "
            "opinion before you act."
        )
    else:
        _bull_label, _bear_label = "Bull score", "Bear score"

    if _failed:
        if _err == "judge_failed":
            st.caption(
                "Judge verdict unavailable — the debate ran but the final call could not be parsed. "
                "The transcript below shows the full exchange; this is an infrastructure hiccup, "
                "not a genuine 50/50 split. Try running the debate again for a fresh verdict."
            )
        else:
            st.caption("Debate could not complete (API unavailable or rate-limited). Try again later.")
    else:
        if _bsc is not None and _brc is not None:
            _c1, _c2 = st.columns(2)
            _c1.metric(_bull_label, f"{_bsc}/100")
            _c2.metric(_bear_label, f"{_brc}/100")
        if _kd:
            st.markdown(f"**Key dispute:** {_kd}")
        if _grd is False:
            st.warning("One or both agents relied on generic arguments — treat this debate with lower confidence.")
    if _trn:
        st.markdown("**Transcript:**")
        for _tr in _trn:
            _ag = (_tr.get("agent") or "").title()
            _ag_color = "#22c55e" if _tr.get("agent") == "bull" else "#ef4444"
            st.markdown(
                f"<span style='color:{_ag_color}'>**Round {_tr.get('round')} — {_ag}:**</span> {_html.escape(str(_tr.get('text', '')))}",
                unsafe_allow_html=True,
            )


def _fmt_action(action: dict) -> tuple[str, str, str]:
    """Format a structured rebalancer/deterioration action dict into
    (color, label, text) so a card renders the directive directly instead of
    a "consider X" prose. Shared by Home's Review Before Close cards and the
    Summary page's simple action cards."""
    t = (action or {}).get("type", "")
    if t == "WATCH":
        # "Watch" is the display label; the comparison above still keys on
        # the internal "WATCH" action type.
        return (_HOME_CALM, "Watch",
                "no action today — see Trigger below for what would escalate.")
    if t == "TIGHTEN_ONLY":
        ns = action.get("new_stop")
        return (_HOME_ELEVATED, "ACT",
                f"Raise stop to ${ns:.2f}." if ns else "Raise stop — ATR unavailable, set manually.")
    if t == "TRIM_AND_TIGHTEN":
        ns = action.get("new_stop")
        stop_str = f" AND raise stop to ${ns:.2f}." if ns else "."
        return (_HOME_ELEVATED, "ACT",
                f"Trim {action['trim_shares']} shares "
                f"(≈${action['trim_dollars']:,.0f}, {action['trim_pct']:.0f}% of position)"
                f"{stop_str}")
    if t == "TRIM_TO_TARGET":
        return (_HOME_ELEVATED, "ACT",
                f"Trim {action['from_weight']:.1f}% → {action['target_weight']:.1f}% "
                f"({action['trim_shares']} shares ≈ ${action['trim_dollars']:,.0f}).")
    if t == "PROTECTIVE_TRIM":
        return (_HOME_ELEVATED, "ACT",
                f"Trim {action['trim_ticker']} (weakest in sector, score "
                f"{action['weakest_score']:.0f}) by {action['trim_shares']} shares "
                f"(≈${action['trim_dollars']:,.0f}). Sector exposure: "
                f"{action['from_exposure']:.1f}% → {action['to_exposure']:.1f}%.")
    if t == "DETERIORATION_WATCH":
        return (_HOME_CALM, "Watch",
                "no action today — early deterioration; watching for follow-through "
                "(see Trigger for what escalates it to a TRIM).")
    return (_HOME_CALM, "—", "—")


def _render_holdings_table(port_df) -> None:
    """Full-position Holdings table — Ticker/Shares/Price/Value/Day Δ%/Total
    Δ%/Weight, tabular-nums, gain/loss colored. Shared by Home and the
    Summary page so both render the identical table from one place. Day Δ%
    joins `_live_prices` (published by the price-strip fragment) since it is
    NOT a column on `port_df`; a missing/stale quote renders "—" rather than
    a fabricated 0.00%."""
    st.subheader(f"💼 Holdings ({len(port_df)})")
    _live_px = st.session_state.get("_live_prices") or {}
    _hold_rows = []
    for _, _hr in port_df.iterrows():
        _ht      = str(_hr["Ticker"])
        _hlive   = _live_px.get(_ht, {})
        _hday    = _hlive.get("change_pct")
        _hprice  = _hlive.get("price", _hr["Price"])
        _htotal  = _hr["P&L (%)"]
        _hshares = _hr["Shares"]
        _hval    = _hr["Market Value"]
        _hweight = _hr["Weight (%)"]
        _hshares_txt = _m(f"{_hshares:,.0f}")
        _hval_txt    = _m(f"${_hval:,.0f}")
        _hday_disp  = f"{_hday:+.2f}%" if _hday is not None else "—"
        _hday_color = (_HOME_GAIN if _hday >= 0 else _HOME_LOSS) if _hday is not None else _HOME_CALM
        _htot_color = _HOME_GAIN if _htotal >= 0 else _HOME_LOSS
        _hold_rows.append(
            f"<tr>"
            f"<td style='padding:9px 14px;border-top:1px solid #1f2937;font-weight:700'>{_ht}</td>"
            f"<td style='padding:9px 14px;border-top:1px solid #1f2937;text-align:right'>{_hshares_txt}</td>"
            f"<td style='padding:9px 14px;border-top:1px solid #1f2937;text-align:right'>${_hprice:,.2f}</td>"
            f"<td style='padding:9px 14px;border-top:1px solid #1f2937;text-align:right'>{_hval_txt}</td>"
            f"<td style='padding:9px 14px;border-top:1px solid #1f2937;text-align:right;color:{_hday_color}'>{_hday_disp}</td>"
            f"<td style='padding:9px 14px;border-top:1px solid #1f2937;text-align:right;color:{_htot_color}'>{_htotal:+.1f}%</td>"
            f"<td style='padding:9px 14px;border-top:1px solid #1f2937;text-align:right'>{_hweight:.1f}%</td>"
            f"</tr>"
        )
    st.markdown(
        "<div style='overflow-x:auto'>"
        "<table style=\"width:100%;border-collapse:collapse;background:#0f172a;"
        "border:1px solid #334155;border-radius:12px;font-family:'JetBrains Mono',ui-monospace,monospace;"
        "font-variant-numeric:tabular-nums;font-size:0.86rem\">"
        "<thead><tr>"
        + "".join(
            f"<th style='text-align:{'left' if _lbl == 'Ticker' else 'right'};padding:10px 14px;"
            f"font-family:Inter,system-ui,sans-serif;font-size:0.7rem;font-weight:700;"
            f"letter-spacing:0.05em;text-transform:uppercase;color:#9ca3af;"
            f"background:#111827;border-bottom:1px solid #334155'>{_lbl}</th>"
            for _lbl in ("Ticker", "Shares", "Price", "Value", "Day Δ%", "Total Δ%", "Weight")
        )
        + "</tr></thead><tbody>"
        + "".join(_hold_rows)
        + "</tbody></table></div>",
        unsafe_allow_html=True,
    )


def _render_section_label(label: str, top_margin: int = 18) -> None:
    """Small-caps zone label for the 🧾 Summary cockpit (BOOK SAFETY / TODAY /
    ACT TODAY / PORTFOLIO HEALTH).

    Module-level because app.py executes top-to-bottom and the page blocks that
    call it run far below (feedback_module_def_order). Takes a literal from the
    call site only — never user or advisor text — so it needs no escaping.
    """
    st.markdown(
        f"<div style='font-size:0.68rem;font-weight:700;letter-spacing:0.1em;"
        f"text-transform:uppercase;color:#6b7280;"
        f"margin:{top_margin}px 0 6px'>{label}</div>",
        unsafe_allow_html=True,
    )


def _render_simple_action_card(item: dict, urgent: bool = False) -> None:
    """Lean Act-Today card for the Summary page: tier badge + ticker +
    one-line rationale — matches the approved Option-A mockup. Deliberately
    NOT the full-featured Home card (no Analyze button, Exit Red-Team debate,
    journal context, or tax notes — those stay Home-only); this is a read-only
    at-a-glance view. Handles both item shapes Home's decision_bucket produces
    (plain dicts with `action`/`directive` text, and `_source == "review"`
    dicts carrying a structured `action` dict for `_fmt_action`)."""
    is_review = item.get("_source") == "review"
    ticker = item.get("ticker") or item.get("event") or ""
    icon = item.get("icon", "")
    if is_review:
        _color, _label, _text = _fmt_action(item.get("action", {}) or {})
        if urgent:
            _color = _HOME_URGENT
        headline = item.get("headline", "")
        text = _text + (f" {headline}" if headline and not _text.endswith(headline) else "")
    else:
        _is_crit = item.get("priority") == "critical"
        _color = _HOME_URGENT if (urgent or _is_crit) else _HOME_ELEVATED
        _label = str(item.get("action", "—"))
        text = item.get("directive") or item.get("why") or item.get("reason") or "—"
    # Pill badge (icon + label) + ticker on its own bold line below, matching
    # the approved Option-A mockup's card anatomy — not inline text.
    #
    # `text` goes through _md_bold (escape first, THEN **x** -> <b>x</b>), not
    # raw. The advisors emit markdown and know nothing about their renderer:
    # risk_advisor bolds DOLLAR LOSS FIGURES on the very TRIM cards this lane
    # carries (e.g. "**$1,240 of unnecessary extra loss**"), so interpolating
    # raw here would print literal asterisks around the number that matters
    # most. This is the class fixed at 9 other sites on 2026-08-28
    # (feedback_streamlit_renderer_mismatch); this function was written for the
    # Summary page, never wired up, and so never received that fix — it was
    # dead code until F-204a. Ticker/label are escaped but not md-converted:
    # they are algorithmic symbols, never prose.
    st.markdown(
        f"<div style='background:#15161a;border:1px solid rgba(255,255,255,0.10);"
        f"border-left:3px solid {_color};border-radius:10px;padding:14px 16px;"
        f"margin-bottom:14px;height:100%'>"
        f"<span style='display:inline-flex;align-items:center;gap:6px;font-size:0.68rem;"
        f"font-weight:700;letter-spacing:0.06em;text-transform:uppercase;padding:3px 10px;"
        f"border-radius:20px;margin-bottom:10px;color:{_color};background:{_color}22'>"
        f"{_safe_html(icon)} {_safe_html(_label)}</span>"
        f"<div style='font-family:\"JetBrains Mono\",ui-monospace,monospace;font-weight:700;"
        f"font-size:1.02rem;margin:4px 0;color:#f9fafb'>{_safe_html(ticker)}</div>"
        f"<div style='color:#c3c2b7;font-size:0.82rem;line-height:1.45'>{_md_bold(text)}</div>"
        f"</div>",
        unsafe_allow_html=True,
    )


def _render_stop_ladder(r: dict, holding: dict, price: float,
                        under_reduce: bool = False, buy_add: bool = False) -> None:
    """Analysis-page explainer + what-if simulator for a HELD position's stop.

    Read-only / educational: it never changes a gate, threshold, or
    recommendation — it only VISUALISES the stop the engine already computed and
    SIMULATES it forward. Faithful by construction: every number comes from
    `portfolio.stop_ladder`, which reuses `protective_stop` + the real ATR
    formula + the real constants; the CURRENT-state active stop is pinned to the
    engine's own `r["stop"]` (via atr_stop_override) so it is bit-exact with the
    "Stop Loss" metric / Brief. Renders nothing unless we have price, avg cost
    and ATR.

    `under_reduce`: the Brief flags this position for reduce/exit — suppress the
    "keep climbing" nudges (next-ratchet, tighten-option) so the explainer never
    softens an active exit directive.

    `buy_add`: rendered on the Buy/Strong-Buy tab of a position you already hold.
    Two stops are in play there and MUST be distinguished: the position is sized
    (shares + R:R) off `r["stop"]` — the ATR fresh-entry stop (or your manual
    stop) — DELIBERATELY, so new capital is risked at today's volatility rather
    than off the tighter stop the existing shares earned (sizing off the ratchet
    would over-buy into strength). The ladder's *active* level is your ratcheted
    PROTECTIVE stop. A note frames both so the two numbers can't read as a
    contradiction; sizing/R:R are unchanged.
    """
    from stock_analyzer.constants import (
        ATR_STOP_MULT, STOP_TIGHTEN_ATR_MULT, STOP_TIGHTEN_MIN_GAIN_PCT, APPROACHING_STOP_GAP_PCT,
        STOP_RATCHET_LEVELS,
    )

    avg_cost = _f(holding.get("Avg Cost"))
    atr_val  = _f(r.get("atr"))
    if not (price and price > 0 and avg_cost > 0 and atr_val > 0):
        return
    shares = int(_f(holding.get("Shares")))

    _manual = str(holding.get("Stop Type")) == "Manual" or r.get("_stop_source") == "manual"
    _manual_stop = _f(holding.get("Stop")) if _manual else None

    # atr_stop_override pins the ladder's ATR stop to the engine's exact value —
    # but ONLY on the non-manual path. When a manual stop is active the Analysis
    # bundle overwrites r["stop"] with the manual price, so passing it as the ATR
    # override would render the manual price under the "2× ATR" label (the very
    # label-vs-number confusion this feature exists to kill). Manual → derive the
    # true ATR stop from atr_val; the active stop stays exact via manual_stop.
    L = stop_ladder(
        price, avg_cost, atr_val,
        tighten_multiplier=STOP_TIGHTEN_ATR_MULT,
        manual_stop=_manual_stop,
        atr_stop_override=None if _manual else (_f(r.get("stop")) or None),
    )
    if not L:
        return

    _active = L["active_stop"]
    # Ratchet ladder description, interpolated from the engine's own levels so
    # the bullet text can never drift from STOP_RATCHET_LEVELS.
    _rl_desc = ", ".join(
        f"+{thr:.0f}% → {'breakeven' if mult <= 0.02 else f'lock +{mult*100:.0f}%'}"
        for thr, mult, _ in sorted(STOP_RATCHET_LEVELS, key=lambda x: x[0])
    )
    with st.expander("🛡️ How your stop is set — and what happens next", expanded=False):
        # ── Buy-add framing: two stops are in play (sizing vs protective) ──────
        # The shares/R:R below size off r["stop"] (ATR fresh-entry, or a manual
        # override); the ladder's active level is the ratcheted protective stop.
        # Name both up front so the different numbers don't read as a bug.
        if buy_add:
            _sizing_stop = _f(r.get("stop"))
            # r["stop"] is the manual price when a manual override is active (the
            # Analysis bundle overwrites it), else the raw ATR fresh-entry stop —
            # so describe the sizing stop by what it actually IS. (A manual stop
            # in the [ATR, ratchet-floor) gap is accepted here but rejected by the
            # portfolio's ratchet gate, so _sizing_stop can be the manual price
            # even in the "different" branch — don't hardcode "ATR" there.)
            if _manual:
                _sz_line = (f"- **Sizing stop ${_sizing_stop:.2f}** — the shares & R:R below are sized off "
                            f"**your manual stop**.")
            else:
                _sz_line = (f"- **Sizing stop ${_sizing_stop:.2f}** — the shares & R:R below are sized off the "
                            f"{ATR_STOP_MULT:g}× ATR fresh-entry stop, on purpose: new capital is risked at "
                            f"today's volatility, not off the tighter stop your existing shares already earned. "
                            f"That keeps the add conservative and avoids over-buying into strength.")
            if _sizing_stop and abs(_sizing_stop - _active) >= 0.01:
                st.info(
                    f"**Adding to a position you hold — two stops are at work:**\n\n"
                    f"{_sz_line}\n"
                    f"- **Protective stop ${_active:.2f}** — the real stop on your combined position (the "
                    f"active level on the ladder below)."
                )
            else:
                st.info(
                    f"**Adding to a position you hold.** Your sizing stop and protective stop are the same "
                    f"right now (**${_active:.2f}**) — the shares & R:R below size off it. The ladder shows how "
                    f"it's built."
                )
            st.caption(
                f"⚠️ Adding at ${price:.2f} raises your blended average cost, which lowers your gain % — it can "
                f"drop you into a lower profit-ratchet tier, lowering the floor that tier had locked. Size adds "
                f"with that in mind."
            )
        # ── A) The stop ladder ────────────────────────────────────────────────
        # Every relevant price level on one number-line. Roles (what each level
        # IS) go in the legend caption + hover — the price cluster is too tight
        # for long inline labels. The stop actually in force is drawn as a large
        # ✓ marker; the losing candidate stop is DIMMED, and a "tightest wins"
        # arrow points to the winner — so "which number binds, and why" reads at
        # a glance (the AAPL case: ratchet tier reached, but the ATR stop binds).
        _src = L["active_source"]
        _mk = [dict(label="Entry", role="your average cost", px=avg_cost,
                    color="#9ca3af", active=False, dim=False)]
        if L["tier_reached"] and L["ratchet_floor"]:
            _mk.append(dict(label=L["ratchet_floor_label"], role="profit-lock floor",
                            px=L["ratchet_floor"], color="#3b82f6",
                            active=(_src == "ratchet"), dim=(_src != "ratchet")))
        _mk.append(dict(label="ATR stop", role=f"volatility floor · price − {ATR_STOP_MULT:g}× ATR",
                        px=L["atr_stop"], color="#f59e0b",
                        active=(_src == "atr"), dim=(_src != "atr")))
        if _src == "manual":
            _mk.append(dict(label="Manual", role="your placed override", px=_active,
                            color="#dc2626", active=True, dim=False))
        if L["tighten_stop"] and _active < L["tighten_stop"] < price:
            # Violet (not amber) so it doesn't blur into the orange ATR stop —
            # the one low-contrast pair on the ladder.
            _mk.append(dict(label="Tighter", role=f"optional · price − {STOP_TIGHTEN_ATR_MULT:g}× ATR",
                            px=L["tighten_stop"], color="#a78bfa", active=False, dim=True))
        _mk.append(dict(label="Now", role="current price", px=price,
                        color="#22c55e", active=False, dim=False))

        _lo = min(m["px"] for m in _mk)
        _hi = max(m["px"] for m in _mk)
        _pad = max((_hi - _lo) * 0.12, atr_val * 0.6)
        _xmin, _xmax = _lo - _pad, _hi + _pad

        _fig = go.Figure()
        # #3 — zones: below the active stop = stop-out territory (red); above it =
        # still holding (green). Makes the cushion legible without reading a number.
        _fig.add_vrect(x0=_xmin, x1=_active, fillcolor="#ef4444", opacity=0.07,
                       line_width=0, layer="below",
                       annotation_text="🛑 stop-out zone", annotation_position="bottom left",
                       annotation_font_size=10, annotation_font_color="#f87171")
        _fig.add_vrect(x0=_active, x1=_xmax, fillcolor="#22c55e", opacity=0.06,
                       line_width=0, layer="below",
                       annotation_text="✅ position zone", annotation_position="bottom right",
                       annotation_font_size=10, annotation_font_color="#86efac")
        _fig.add_vline(x=_active, line_dash="solid", line_color="#dc2626", line_width=1.4)
        _fig.add_vline(x=price, line_dash="dash", line_color="#e5e7eb", line_width=1)
        # #2 — "tightest wins" arrow, only when there's an actual contest (a
        # ratchet floor and/or a manual override competing with the ATR stop).
        if L["tier_reached"] or _src == "manual":
            _fig.add_annotation(
                x=_active, y=0.10, text="tightest of these wins → your stop",
                showarrow=True, arrowhead=2, arrowsize=1, arrowwidth=1.2,
                arrowcolor="#dc2626", ax=0, ay=-34, xref="x", yref="y",
                font=dict(size=10, color="#fca5a5"),
            )
        for i, m in enumerate(_mk):
            _icon = "✓ " if m["active"] else ""
            _size = 20 if m["active"] else 11
            _op   = 0.9 if m["active"] else (0.4 if m["dim"] else 0.95)
            _sym  = "star" if m["active"] else "circle"
            _txt  = f"<b>{_icon}{m['label']}</b><br>${m['px']:.2f}" if m["active"] else f"{m['label']}<br>${m['px']:.2f}"
            _fig.add_trace(go.Scatter(
                x=[m["px"]], y=[0], mode="markers+text",
                marker=dict(size=_size, color=m["color"], symbol=_sym, opacity=_op,
                            line=dict(width=1, color="#0e1117")),
                text=[_txt],
                textposition="bottom center" if (m["active"] or i % 2 == 1) else "top center",
                textfont=dict(size=11, color=m["color"]),
                hovertext=[f"{m['label']} — {m['role']}: ${m['px']:.2f}"],
                hoverinfo="text", showlegend=False,
            ))
        _fig.update_layout(
            height=240, template="plotly_dark", showlegend=False,
            margin=dict(l=10, r=10, t=44, b=10),
            xaxis=dict(title="Price ($)", range=[_xmin, _xmax], zeroline=False),
            yaxis=dict(visible=False, range=[-1, 1]),
        )
        st.plotly_chart(_fig, width="stretch", key=f"stopladder_{holding.get('Ticker','')}")
        # #1 — role legend (colour → what it means), so the short chart labels
        # never need a paragraph next to them.
        _leg = " &nbsp;·&nbsp; ".join(
            f"<span style='color:{m['color']}'>⬤</span> {m['label']} "
            f"<span style='color:#9ca3af'>({m['role']})</span>"
            + (" — <b>in force</b>" if m["active"] else "")
            for m in _mk
        )
        st.caption(f"−{L['gap_pct']:.1f}% cushion to the active stop.")
        st.markdown(f"<div style='font-size:0.82em;line-height:1.6'>{_leg}</div>",
                    unsafe_allow_html=True)

        # ── #4 — Profit-lock staircase ────────────────────────────────────────
        # The forward story: as price climbs through each ratchet trigger, the
        # LOCKED floor steps up. Shows the whole path + where you sit on it, so
        # the next logical rung is obvious. Suppressed under a reduce/exit call
        # (same reason the "keep-climbing" captions are). The dotted line marks
        # your ACTUAL stop today — when it sits above the floor, the ATR stop is
        # what binds (ties back to the "tightest wins" story above).
        _rungs = L["ratchet_rungs"]
        if not under_reduce and _rungs:
            st.markdown("**📈 Profit-lock staircase — how your stop floor climbs as you gain**")
            _xs = [rr["trigger_price"] for rr in _rungs]
            _ys = [rr["floor"] for rr in _rungs]
            _sfig = go.Figure()
            # Stepped floor line (holds, then jumps up at each trigger price).
            _sfig.add_trace(go.Scatter(
                x=_xs + [max(_xs[-1], price) * 1.06], y=_ys + [_ys[-1]],
                mode="lines", line=dict(shape="hv", color="#3b82f6", width=2),
                hoverinfo="skip", showlegend=False,
            ))
            # Rung markers — reached = green, ahead = grey; the current tier ringed.
            _sfig.add_trace(go.Scatter(
                x=_xs, y=_ys, mode="markers+text",
                marker=dict(
                    size=[16 if rr["is_current"] else 11 for rr in _rungs],
                    color=["#22c55e" if rr["reached"] else "#6b7280" for rr in _rungs],
                    line=dict(width=[2 if rr["is_current"] else 0 for rr in _rungs], color="#e5e7eb"),
                ),
                text=[f"+{rr['gain_pct']:.0f}% → ${rr['floor']:.2f}" for rr in _rungs],
                textposition="top center", textfont=dict(size=10, color="#93c5fd"),
                hovertext=[f"At ${rr['trigger_price']:.2f} (+{rr['gain_pct']:.0f}%): "
                           f"stop locks ${rr['floor']:.2f} (+{rr['floor_pct']:.0f}%) — {rr['label']}"
                           for rr in _rungs],
                hoverinfo="text", showlegend=False,
            ))
            _sfig.add_vline(x=price, line_dash="dash", line_color="#e5e7eb", line_width=1,
                            annotation_text=f"you are here · +{L['gain_pct']:.1f}%",
                            annotation_position="top", annotation_font_size=10,
                            annotation_font_color="#e5e7eb")
            _sfig.add_hline(y=_active, line_dash="dot", line_color="#f59e0b", line_width=1,
                            annotation_text=f"actual stop today ${_active:.2f}",
                            annotation_position="bottom right", annotation_font_size=10,
                            annotation_font_color="#fbbf24")
            _sfig.update_layout(
                height=230, template="plotly_dark", showlegend=False,
                margin=dict(l=10, r=10, t=30, b=30),
                xaxis=dict(title="Price ($)",
                           range=[min(avg_cost, price) * 0.97, max(_xs[-1], price) * 1.08]),
                # Force the y-range to include the actual-stop hline — an
                # add_hline shape does NOT expand autorange, so the "actual stop
                # today" line would clip out of view exactly when the ATR stop
                # binds below the lowest floor (early positions) or a big-winner
                # trailing stop sits above the top floor — the cases this chart
                # exists to explain.
                yaxis=dict(title="Locked stop floor ($)",
                           range=[min(min(_ys), _active) * 0.98, max(max(_ys), _active) * 1.02]),
            )
            st.plotly_chart(_sfig, width="stretch", key=f"stopstair_{holding.get('Ticker','')}")
            if _src == "manual":
                _stair_cap = (
                    "Green = tier reached · grey = ahead · ringed = your current tier. The floor is the "
                    "profit-ratchet level only — your **actual** stop (dotted) is your manual override, which is in force."
                )
            else:
                _stair_cap = (
                    "Green = tier reached · grey = ahead · ringed = your current tier. The floor is the "
                    f"profit-ratchet level only — your **actual** stop is the higher of it and the {ATR_STOP_MULT:g}× "
                    "ATR stop (dotted), so early on the ATR stop usually binds."
                )
            st.caption(_stair_cap)

        # ── B) Plain-English walk-through (with THIS position's numbers) ───────
        if L["active_source"] == "atr":
            _src_line = (
                f"the **ATR stop** (${L['atr_stop']:.2f}) — you're up +{L['gain_pct']:.1f}%, below the "
                f"+10% profit-ratchet, so the volatility stop is in force."
                if not L["tier_reached"] else
                f"the **ATR stop** (${L['atr_stop']:.2f})."
            )
        elif L["active_source"] == "ratchet":
            _src_line = (
                f"the **{L['ratchet_floor_label']}** floor (${L['ratchet_floor']:.2f}) — your gain lifted it "
                f"above the ATR stop."
            )
        else:  # manual
            _src_line = f"**your manual stop** (${_active:.2f}) — it overrides the computed stop because it's tighter."
        _tier_note = ""
        if L["tier_reached"] and L["active_source"] == "atr":
            _tier_note = (
                f" You're in the **{L['tier_label']}** tier (up +{L['gain_pct']:.1f}%), so the label reads "
                f"“{L['tier_label']}” — but that floor is only ${L['ratchet_floor']:.2f}, *below* the ATR "
                f"stop, so the **ATR stop is the number that actually protects you** right now. The label "
                f"marks the profit tier you've reached; the value comes from volatility."
            )
        st.markdown(
            f"Your stop is built from **three layers**, and each run the app uses the **tightest (highest)** of them:\n\n"
            f"1. **Volatility floor (ATR).** ATR(14) ≈ **${atr_val:.2f}**/day of typical range. The base stop sits "
            f"**{ATR_STOP_MULT:g}× ATR** below price = **${L['atr_stop']:.2f}** — outside normal day-to-day noise.\n"
            f"2. **Profit ratchet.** As your gain grows, a floor lifts to protect profit "
            f"({_rl_desc}). The app raises the recommended stop for you to place — the lock comes from you "
            f"moving your broker stop up and never lowering it.\n"
            f"3. **Your override.** A manual stop you've placed wins whenever it's tighter than the computed one.\n\n"
            f"**Right now:** price **${price:.2f}**, up **+{L['gain_pct']:.1f}%**. Your active stop is {_src_line}"
            f"{_tier_note}"
        )
        if (not under_reduce and L["tighten_stop"] and _active < L["tighten_stop"] < price
                and L["gain_pct"] >= STOP_TIGHTEN_MIN_GAIN_PCT):
            st.caption(
                f"💡 A **tighter alternative** sits at **${L['tighten_stop']:.2f}** ({STOP_TIGHTEN_ATR_MULT:g}× ATR). Today's Brief "
                f"nudges toward it when you're up ≥ {STOP_TIGHTEN_MIN_GAIN_PCT:.0f}% with "
                f"{APPROACHING_STOP_GAP_PCT:.0f}%-or-less room — it locks more profit at the cost of less "
                f"breathing room. Optional, not required."
            )
        if L["next_tier"] and not under_reduce:
            _nt = L["next_tier"]
            st.caption(
                f"🎯 **Next ratchet up:** if it reaches **${_nt['trigger_price']:.2f}** (+{_nt['gain_pct']:.0f}%), "
                f"the app will recommend raising your stop to **${_nt['floor']:.2f}** — locking **{_nt['label']}** "
                f"once you place it."
            )

        # ── C) What-if simulator ──────────────────────────────────────────────
        st.markdown("**🎮 What-if — drag to a price and see what your stop does:**")
        _smin = round(min(avg_cost, _active) * 0.85, 2)
        _smax = round(price * 1.40, 2)
        _step = max(0.01, round(price * 0.005, 2))
        _sdefault = min(max(round(price, 2), _smin), _smax)  # clamp into range
        _hypo = st.slider(
            "Simulated price ($)", min_value=_smin, max_value=_smax, value=_sdefault,
            step=_step, key=f"stopsim_{holding.get('Ticker','')}",
            help="Assumes today's volatility (ATR held constant). Downside = tested against the stop you have TODAY; upside = the higher stop the app would then recommend.",
        )
        if _hypo < price:
            # Downside: does a fall to _hypo breach the stop you hold TODAY? (The
            # app instructs you to place a resting stop at the active level, so we
            # test against that placed level, not a recomputed one.)
            _drop = (_hypo / price - 1) * 100
            if _hypo <= _active:
                _realized_pct = (_active / avg_cost - 1) * 100
                _realized = (_active - avg_cost) * shares
                _outcome = (
                    f"locking in <b>{_realized_pct:+.1f}%</b> (<b>${_realized:+,.0f}</b> on {shares} shares) — "
                    f"a profitable exit, not a loss."
                    if _active >= avg_cost else
                    f"realizing <b>{_realized_pct:+.1f}%</b> (<b>${_realized:+,.0f}</b> on {shares} shares) — "
                    f"the loss is capped here, by design."
                )
                st.markdown(
                    f"<div style='padding:10px 14px;border-radius:6px;background:#dc262618;"
                    f"border-left:4px solid #dc2626;color:#fca5a5'>🛑 <b>Stop-out.</b> A fall to "
                    f"<b>${_hypo:.2f}</b> ({_drop:+.1f}%) breaches your <b>${_active:.2f}</b> stop. "
                    f"You'd exit near the stop, {_outcome}</div>", unsafe_allow_html=True,
                )
            else:
                _cushion = (_hypo - _active) / _hypo * 100
                st.markdown(
                    f"<div style='padding:10px 14px;border-radius:6px;background:#16a34a14;"
                    f"border-left:4px solid #22c55e;color:#86efac'>✅ <b>No exit.</b> At "
                    f"<b>${_hypo:.2f}</b> ({_drop:+.1f}%) you'd still sit <b>{_cushion:.1f}%</b> above your "
                    f"<b>${_active:.2f}</b> stop — the position keeps running.</div>",
                    unsafe_allow_html=True,
                )
        else:
            # Upside: recompute the RECOMMENDED stop at the higher price. The
            # engine is stateless — it re-derives max(2×ATR stop, current-tier
            # floor) every run — so this is the level the app would tell you to
            # RAISE your stop to, not an automatic guarantee. The floor recedes if
            # the gain later falls into a lower tier; protection is realised only
            # by you moving your placed stop up and not lowering it.
            _sim = stop_ladder(_hypo, avg_cost, atr_val,
                               tighten_multiplier=STOP_TIGHTEN_ATR_MULT, manual_stop=_manual_stop,
                               atr_stop_override=round(_hypo - L["atr_multiplier"] * atr_val, 2))
            _new_stop = _sim["active_stop"]
            _new_pct = (_new_stop / avg_cost - 1) * 100
            _new_amt = (_new_stop - avg_cost) * shares
            _driver = (f"the <b>{_sim['ratchet_floor_label']}</b> floor"
                       if _sim["active_source"] == "ratchet" else "the 2× ATR trailing stop")
            _tier_txt = (f" You'd enter the <b>{_sim['tier_label']}</b> profit tier (floor ${_sim['ratchet_floor']:.2f})."
                         if _sim["tier_reached"] else "")
            _note = (" Today's Brief already flags this position for reduce/exit — treat this as informational."
                     if under_reduce else "")
            st.markdown(
                f"<div style='padding:10px 14px;border-radius:6px;background:#1e3a8a24;"
                f"border-left:4px solid #3b82f6;color:#bfdbfe'>📈 <b>At ${_hypo:.2f} "
                f"(+{_sim['gain_pct']:.1f}%)</b>, the app would recommend raising your stop to "
                f"<b>${_new_stop:.2f}</b> ({_driver}) — protecting <b>{_new_pct:+.1f}%</b> "
                f"(<b>${_new_amt:+,.0f}</b>) once you place it there and hold it.{_tier_txt}{_note}</div>",
                unsafe_allow_html=True,
            )
        st.caption(
            "Educational only — this mirrors the engine's stop logic; it doesn't change any recommendation. "
            "Stops are acted at the next open, not intraday."
        )


def _render_trade_button(
    ticker: str,
    suggested_action: str = "BUY",
    signal_context: str = "",
    price: float | None = None,
    shares: float | None = None,
    trigger: str = "RECOMMENDATION",
    followed_intent: str | None = None,
    notes: str = "",
    key_suffix: str = "",
    label: str | None = None,
    width: str = "content",
) -> None:
    """
    Render a "📒 Trade {ticker}" button that, on click, stages prefill values
    into session_state and navigates to the Trade Journal page.

    The Trade Journal form reads these keys on its next render:
      _tj_prefill   — ticker / action / shares / price / trigger / notes
      _tj_signal_seen  — the reconciled verdict at point of click (e.g.
                         "Composite Sell · 42/100"), so the Decision Context
                         block becomes passive capture instead of typing work
      _tj_followed     — "Yes / No / Discretionary" radio default

    followed_intent values: 'yes', 'no', 'discretionary' — maps to the radio
    label strings expected by the form. Leave as None to skip the auto-set
    (user will pick manually).
    """
    _label = label or f"📒 Trade {ticker}"
    _key   = f"_trade_btn_{ticker}_{key_suffix or 'default'}"
    if st.button(_label, key=_key, width=width,
                 disabled=st.session_state.get("_readonly", False)):
        _prefill: dict = {
            "ticker":  ticker.upper(),
            "action":  suggested_action.upper(),
            "trigger": trigger,
            "notes":   notes,
        }
        if price is not None and price > 0:
            _prefill["price"]  = float(price)
        if shares is not None and shares > 0:
            _prefill["shares"] = float(shares)
        st.session_state["_tj_prefill"] = _prefill
        # Stash into non-widget-bound _pending keys. Direct writes to
        # widget-bound session_state keys (_tj_signal_seen, _tj_followed)
        # raise StreamlitAPIException once those widgets have rendered in a
        # previous run — which would silently abort this click handler and
        # skip the navigation. Trade Journal page consumes these on next render.
        if signal_context:
            st.session_state["_tj_signal_seen_pending"] = signal_context
        if followed_intent:
            _followed_map = {
                "yes":           "Yes — followed signal",
                "no":            "No — overrode signal",
                "discretionary": "No signal — discretionary",
            }
            st.session_state["_tj_followed_pending"] = _followed_map.get(
                followed_intent, "— (skip)"
            )
        st.session_state["_pending_page"] = "📒 Trade Journal"
        st.rerun()


def _build_premortem_case(ticker: str) -> dict | None:
    """
    Concept C (Pre-Mortem Protocol): assemble the composite-pillar / portfolio-
    concentration / macro / earnings evidence and call the LLM ONCE for the
    case against buying `ticker`. Called only from the explicit "Run
    Pre-Mortem" button click — never on every rerun, so typing in the
    pre-commitment box afterward can't re-trigger the LLM call.

    Returns None on any failure (no API key, API error, malformed/short/
    generic response). This is the aid, not the gate: the required
    pre-commitment text box is enforced independently in the submit handler,
    so a missing/failed case-against never blocks a legitimate Buy.
    """
    _pm_bundle = (st.session_state.get("_grow_composites") or {}).get(ticker)
    if _pm_bundle is None:
        try:
            _pm_bundle = load_all(ticker, period="6mo")
        except Exception:
            _pm_bundle = None
    _pm_bundle = _pm_bundle or {}

    _pm_pillar = _pm_advisor.driving_pillar_from_bundle(_pm_bundle)
    _pm_engine = {
        "composite":       _pm_bundle.get("total"),
        "band":            (_pm_bundle.get("rec") or {}).get("label"),
        "driving_pillar":  _pm_pillar["driving_pillar"],
        "driving_signals": _pm_pillar["driving_signals"],
    }

    _pm_portfolio: dict = {}
    try:
        _pm_pdf = st.session_state.get("_port_df_enriched")
        if _pm_pdf is not None and not _pm_pdf.empty:
            _pm_portfolio["n_positions"] = int(len(_pm_pdf))
            if {"Sector", "Market Value"}.issubset(_pm_pdf.columns):
                _pm_by_sec = _pm_pdf.groupby("Sector")["Market Value"].sum()
                _pm_total  = float(_pm_pdf["Market Value"].sum())
                if _pm_total > 0 and not _pm_by_sec.empty:
                    _pm_portfolio["top_sector"]            = str(_pm_by_sec.idxmax())
                    _pm_portfolio["top_sector_weight_pct"] = float(_pm_by_sec.max() / _pm_total * 100.0)
        if _pm_bundle.get("sector"):
            _pm_portfolio["this_sector"] = _pm_bundle.get("sector")
    except Exception:
        pass

    _pm_macro: dict = {}
    try:
        for _pm_k, _pm_v in st.session_state.items():
            if isinstance(_pm_k, str) and _pm_k.startswith("_macro_regime_") and _pm_v:
                _pm_macro = {"label": _pm_v.get("label"), "confidence": _pm_v.get("confidence")}
                break
    except Exception:
        pass

    _pm_earnings: dict = {}
    try:
        _pm_ec = db.load_earnings_context(ticker)
        if _pm_ec:
            _pm_parts = []
            if _pm_ec.get("beat_rate_pct") is not None:
                _pm_parts.append(f"historical beat rate {_pm_ec['beat_rate_pct']:.0f}%")
            if _pm_ec.get("recent_reaction_direction"):
                _pm_parts.append(f"recent reaction pattern: {_pm_ec['recent_reaction_direction']}")
            if _pm_ec.get("what_to_watch_cnbc"):
                _pm_parts.append(str(_pm_ec["what_to_watch_cnbc"]))
            _pm_earnings = {
                "next_earnings_date": _pm_ec.get("earnings_date"),
                "note": "; ".join(_pm_parts) if _pm_parts else None,
            }
    except Exception:
        pass

    _pm_lessons: list[str] = []
    try:
        _pm_tdf = st.session_state.get("trades_df")
        if _pm_tdf is not None and not _pm_tdf.empty and "lesson_category" in _pm_tdf.columns:
            _pm_sells = _pm_tdf[_pm_tdf["action"].str.upper() == "SELL"].copy()
            _pm_ticker_sells = (
                _pm_sells[_pm_sells["ticker"] == ticker]
                if "ticker" in _pm_sells.columns
                else _pm_sells.iloc[:0]
            )
            _pm_src = _pm_ticker_sells if not _pm_ticker_sells.empty else _pm_sells
            _pm_lessons = (
                _pm_src["lesson_category"]
                .dropna()
                .loc[lambda s: s.str.strip() != ""]
                .sort_index(ascending=False)
                .head(5)
                .tolist()
            )
    except Exception:
        pass

    _pm_api_key = (
        st.secrets.get("anthropic", {}).get("api_key", "") if hasattr(st, "secrets") else ""
    )
    if not _pm_api_key:
        return None

    _pm_inputs = _pm_advisor.build_premortem_inputs(
        ticker, engine=_pm_engine, portfolio=_pm_portfolio,
        macro=_pm_macro, earnings=_pm_earnings,
        recent_lessons=_pm_lessons,
    )
    return _pm_advisor.generate_case_against(ticker, _pm_inputs, _pm_api_key)


_PT_CLR = {
    "price": "#94a3b8", "win": "#22c55e", "loss": "#ef4444",
    "signal": "#60a5fa", "self": "#a78bfa", "open": "#3b82f6",
    "surface": "#111827", "grid": "#1f2937", "zero": "#4b5563",
    "muted": "#6b7280", "ghost": "#9ca3af",
}


def _pt_money(v, signed: bool = True) -> str:
    """Format money for Streamlit *markdown* (not HTML).

    The '$' is backslash-escaped because Streamlit's markdown treats a bare
    `$...$` pair as LaTeX — two unescaped dollar amounts on the same line
    silently render as maths instead of prices.
    """
    if v is None:
        return "—"
    _sign = ("+" if v >= 0 else "−") if signed else ""
    return f"{_sign}\\${abs(v):,.2f}" if abs(v) < 1000 else f"{_sign}\\${abs(v):,.0f}"


def _pt_pct(v, signed: bool = True) -> str:
    """Percent for markdown; '—' when genuinely unknown (never 0 as a stand-in)."""
    if v is None:
        return "—"
    return f"{v:+.1f}%" if signed else f"{v:.1f}%"


def _prior_trades_pointer(ticker: str, hist: dict | None, price,
                          include_last_exit: bool = True) -> str:
    """F-237 Phase 2: the one-line Trade Plan pointer to a ticker's own history.

    Exists because Prior Trades only helps if the user thinks to click the tab;
    this surfaces the same facts on the surface they actually land on.

    STRICTLY FACTUAL — a count, a net dollar figure, and the last exit price
    against today's. It deliberately carries **no alpha or vs-SPY number and no
    verdict on the user's skill in the name**: an outcome/alpha judgment at the
    decision moment is the class explicitly rejected for Self Track Record
    (memory `project_self_track_record`), because it editorialises on the very
    decision the user is weighing. Ticker-specific *facts* are the accepted
    class — F-195 already feeds prior lessons into the Pre-Mortem at BUY.

    Never gates: the caller renders this as an info note and nothing reads it.
    Returns "" when there's nothing truthful to say, so callers can render
    unconditionally.
    """
    if not hist:
        return ""
    _eps = hist.get("episodes", [])
    if not _eps:
        return ""
    _t     = hist.get("totals", {})
    _n_rt  = _t.get("n_round_trips", 0)
    _n_op  = _t.get("n_open", 0)
    _net   = _t.get("net_realized")
    _first = _t.get("first_entry_date")

    # Most recent CLOSED exit (episodes are newest-first)
    _xp, _xd = None, None
    for _ep in _eps:
        if _ep.get("status") == "closed":
            _xp, _xd = _ep.get("exit_avg"), _ep.get("exit_date")
            break

    # A journal gap means net_realized is UNDERSTATED, not merely uncertain:
    # orphan SELLs and unparseable rows are skipped outright, so their P&L never
    # enters the total. The tab surfaces every warning as a visible banner; the
    # pointer must not state the bare figure with more confidence than the tab
    # one click away. (`oversell` / `split_in_window` are excluded here — those
    # distort percentages and per-share prices, neither of which this prints.)
    _gap = {_w.get("kind") for _w in hist.get("warnings", [])} & {
        "orphan_sell", "bad_row"
    }

    if not _n_rt:
        # Held, never closed. Suppressed on the exit branch: it says nothing
        # about an exit decision and reads as a remark on the user's selling.
        if _n_op and _first and include_last_exit:
            return (f"🧾 You've held **{ticker}** since "
                    f"**{_first.strftime('%d %b %Y')}** — no prior round trips "
                    f"in this name. → see the **🧾 Prior Trades** tab.")
        return ""

    _bits = [
        f"🧾 **You've traded {ticker} before** — "
        f"**{_n_rt}** closed round trip{'s' if _n_rt != 1 else ''}"
        + (" plus the position you hold now" if _n_op else "")
    ]
    if _first:
        _bits.append(f", first entered {_first.strftime('%b %Y')}")
    if _net is not None:
        _bits.append(f". Net realized **{_pt_money(_net)}**"
                     + (" *(journal gap — see the tab)*" if _gap else ""))
    _bits.append(".")
    # The exit→today comparison is deliberately SUPPRESSED on the Exit Plan.
    # Under a protective "exit this position" call, "your last exit was $118;
    # it's $160 today" reads as "last time you sold, it kept going up" — a
    # counter-argument to the recommendation it sits beneath. On the Buy side
    # the same fact is the accepted anchoring trade-off (plan §8); on the Sell
    # side it would undercut protect-capital-overrides-deploy-capital.
    if include_last_exit and _xp and _xd and price:
        _bits.append(
            f" Your last exit was **{_pt_money(_xp, signed=False)}** on "
            f"{_xd.strftime('%d %b %Y')}; it's "
            f"**{_pt_money(price, signed=False)}** today."
        )
    _bits.append(" → see the **🧾 Prior Trades** tab.")
    return "".join(_bits)


def _prior_trades_figure(hist: dict, px_df, series: list):
    """Two-row Plotly figure for the 🧾 Prior Trades tab (F-237).

    Row 1 — the ticker's price with the user's own fills marked and each
    holding period shaded (green/red by that round trip's outcome).
    Row 2 — position P&L % while held, plus a dashed "had you held"
    continuation running from the most recent exit to today.

    Deliberately TWO ROWS sharing one x-axis, never one plot with two y-axes:
    a dual-axis chart aligns two arbitrary scales and manufactures a
    correlation that isn't in the data.

    Awareness only — nothing here feeds a score, a gate, or a verdict.
    Returns None when there is nothing chartable (no price history, or no
    reconstructed episodes) so the caller falls back to the cards alone.
    """
    if px_df is None or getattr(px_df, "empty", True) or "Close" not in px_df.columns:
        return None
    episodes = hist["episodes"] if hist else []
    if not episodes:
        return None
    _close = px_df["Close"].dropna()
    if _close.empty:
        return None

    fig = make_subplots(
        rows=2, cols=1, shared_xaxes=True,
        row_heights=[0.62, 0.38], vertical_spacing=0.08,
        subplot_titles=("", "Position P&L while held"),
    )

    # ── Row 1: price line ────────────────────────────────────────────────
    fig.add_trace(go.Scatter(
        x=_close.index, y=_close.values, mode="lines", name=hist["ticker"],
        line=dict(color=_PT_CLR["price"], width=2),
        hovertemplate="%{x|%d %b %Y}<br>$%{y:.2f}<extra></extra>",
    ), row=1, col=1)

    # ── Held bands, spanning BOTH rows so the panels read together ───────
    _last_x = _close.index[-1]
    for _ep in episodes:
        _rp = _ep.get("realized_pnl")
        if _ep.get("status") == "open":
            _band = _PT_CLR["open"]
        elif _rp is not None and _rp > 0:
            _band = _PT_CLR["win"]
        elif _rp is not None and _rp < 0:
            _band = _PT_CLR["loss"]
        else:
            _band = _PT_CLR["muted"]
        # Added per-row rather than row="all": with shared_xaxes the "all"
        # form only painted the price panel, so the band stopped at the
        # bottom of row 1 and the two panels didn't visually read together.
        for _band_row in (1, 2):
            try:
                fig.add_vrect(
                    x0=_ep["entry_date"],
                    x1=_ep["exit_date"] if _ep.get("exit_date") else _last_x,
                    fillcolor=_band, opacity=0.08, line_width=0,
                    layer="below", row=_band_row, col=1,
                )
            except Exception:
                pass

    # ── Fill markers. Shape carries buy/sell as well as colour, so identity
    # survives colour-vision deficiency.
    #
    # Sells split THREE ways, not two. The earlier two-way split (stop-out vs
    # "sold on signal") put every MANUAL exit in the signal bucket, so a
    # self-initiated sell was labelled as one the engine called — on a card
    # whose own badge said SELF-INITIATED. That misrepresents the user's own
    # history, which is the one thing this tab exists to get right.
    _buys: list = []
    _sell_sig: list = []
    _sell_self: list = []
    _sell_stop: list = []
    for _ep in episodes:
        _ep_trg = [str(_t).upper() for _t in _ep.get("trigger_types", [])]
        _ep_stop = any("STOP" in _t for _t in _ep_trg)
        _ep_rec  = any("RECOMMENDATION" in _t for _t in _ep_trg)
        for _fl in _ep.get("fills", []):
            _act = str(_fl.get("action", "")).upper()
            _trg = str(_fl.get("trigger_type", "") or "").upper()
            _pt_row = (_fl.get("date"), _fl.get("price"), _fl.get("shares"))
            if "BUY" in _act:
                _buys.append(_pt_row)
            elif "SELL" in _act:
                # Per-fill trigger wins; fall back to the episode's trigger set
                # only for legacy rows with no per-fill trigger captured.
                if "STOP" in _trg or (not _trg and _ep_stop):
                    _sell_stop.append(_pt_row)
                elif "RECOMMENDATION" in _trg or (not _trg and _ep_rec):
                    _sell_sig.append(_pt_row)
                else:
                    _sell_self.append(_pt_row)

    for _pts, _nm, _sym, _clr in (
        (_buys,      "Your buy",       "triangle-up",   _PT_CLR["win"]),
        (_sell_sig,  "Sold on signal", "triangle-down", _PT_CLR["signal"]),
        (_sell_self, "Sold yourself",  "triangle-down", _PT_CLR["self"]),
        (_sell_stop, "Stopped out",    "triangle-down", _PT_CLR["loss"]),
    ):
        if not _pts:
            continue
        fig.add_trace(go.Scatter(
            x=[p[0] for p in _pts], y=[p[1] for p in _pts],
            mode="markers", name=_nm,
            marker=dict(symbol=_sym, size=12, color=_clr,
                        line=dict(color=_PT_CLR["surface"], width=2)),
            customdata=[p[2] for p in _pts],
            hovertemplate=(_nm + "<br>%{x|%d %b %Y}<br>"
                           "%{customdata:,.0f} sh @ $%{y:.2f}<extra></extra>"),
        ), row=1, col=1)

    # Today's close — the anchor for "is it expensive vs what I've paid?"
    fig.add_trace(go.Scatter(
        x=[_last_x], y=[float(_close.iloc[-1])], mode="markers+text",
        name="Today", showlegend=False,
        marker=dict(size=9, color="#f9fafb",
                    line=dict(color=_PT_CLR["surface"], width=2)),
        text=[f"  ${float(_close.iloc[-1]):.2f} today"],
        textposition="middle left", textfont=dict(size=11, color="#f9fafb"),
        hoverinfo="skip",
    ), row=1, col=1)

    # ── Row 2: one P&L arc per episode ───────────────────────────────────
    for _s in (series or []):
        if not _s.get("dates"):
            continue
        # is_win is None for an exactly-breakeven trip — paint it neutral
        # rather than red, matching the vrect band logic above.
        _win = _s.get("is_win")
        if _s.get("status") == "open":
            _c = _PT_CLR["open"]
        elif _win is True:
            _c = _PT_CLR["win"]
        elif _win is False:
            _c = _PT_CLR["loss"]
        else:
            _c = _PT_CLR["muted"]
        fig.add_trace(go.Scatter(
            x=_s["dates"], y=_s["pct"], mode="lines", showlegend=False,
            line=dict(color=_c, width=2.5),
            hovertemplate="%{x|%d %b %Y}<br>%{y:+.1f}%<extra></extra>",
        ), row=2, col=1)
        if _s.get("ghost_dates"):
            # Neutral grey, NOT the episode's win/loss colour. The ghost is a
            # hypothetical, not an outcome — and inheriting the colour drew a
            # RISING line in the loss red when a sold-at-a-loss name recovered,
            # which reads as a contradiction.
            fig.add_trace(go.Scatter(
                x=_s["ghost_dates"], y=_s["ghost_pct"], mode="lines",
                name="Had you held (vs your cost)", opacity=0.55,
                line=dict(color=_PT_CLR["ghost"], width=2, dash="dash"),
                hovertemplate=("had you held<br>%{x|%d %b %Y}"
                               "<br>%{y:+.1f}%<extra></extra>"),
            ), row=2, col=1)
            # Direct end-label, so the hypothetical's magnitude is readable
            # without hovering (the mockup had this; the first build lost it).
            if _s["ghost_pct"]:
                fig.add_trace(go.Scatter(
                    x=[_s["ghost_dates"][-1]], y=[_s["ghost_pct"][-1]],
                    mode="markers+text", showlegend=False,
                    marker=dict(size=7, color="rgba(0,0,0,0)",
                                line=dict(color=_PT_CLR["ghost"], width=2)),
                    text=[f"  had you held: {_s['ghost_pct'][-1]:+.1f}%"],
                    textposition="middle left",
                    textfont=dict(size=11, color=_PT_CLR["ghost"]),
                    hoverinfo="skip",
                ), row=2, col=1)

    fig.add_hline(y=0, line_color=_PT_CLR["zero"], line_width=1.5,
                  row=2, col=1)

    fig.update_layout(
        template="plotly_dark", height=520, hovermode="x unified",
        margin=dict(l=10, r=10, t=46, b=10),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        legend=dict(orientation="h", yanchor="bottom", y=1.04,
                    xanchor="left", x=0, font=dict(size=11)),
    )
    fig.update_xaxes(showgrid=False, zeroline=False)
    fig.update_yaxes(gridcolor=_PT_CLR["grid"], zeroline=False,
                     tickprefix="$", row=1, col=1)
    fig.update_yaxes(gridcolor=_PT_CLR["grid"], zeroline=False,
                     ticksuffix="%", row=2, col=1)
    for _ann in fig.layout.annotations:
        _ann.font.size = 11
        _ann.font.color = "#9ca3af"
    return fig


def _tax_exit_note_html(ticker: str | None) -> str:
    """Concept F: amber holding-period note for an EXIT/TRIM card when the
    position is within TAX_LONGTERM_WINDOW_DAYS of long-term-gains eligibility.

    Awareness-only — this NEVER gates, suppresses, sizes, or reorders a
    recommendation; the investment signal on the card is unchanged. Returns ""
    when not applicable (no ticker, no open lots, already long-term, or beyond
    the window) so a caller can concatenate it unconditionally. Reads only the
    trade journal already in session state — no API calls.
    """
    if not ticker:
        return ""
    try:
        from stock_analyzer.constants import TAX_RATE_SHORT_TERM as _TRS, TAX_RATE_LONG_TERM as _TRL
        _hp = holding_period_status(ticker, st.session_state.get("trades_df"))
        if not _hp or not _hp.get("near_ltcg"):
            return ""
        _n  = int(_hp["days_to_ltcg"])
        _pp = int(round((_TRS - _TRL) * 100))
        return (
            f"<div style='color:#fbbf24;font-size:0.78em;margin-top:6px;"
            f"border-left:2px solid #f59e0b;padding-left:8px'>"
            f"🧾 <b>Tax note:</b> becomes long-term-gains eligible in "
            f"{_n} day{'s' if _n != 1 else ''}. If you'd be selling at a gain, "
            f"waiting until then can cut the tax rate on this position "
            f"(≈{_pp}pp). Context only — the recommendation above is unchanged."
            f"</div>"
        )
    except Exception:
        return ""


def _coord_cache_state(key: str) -> str:
    """Distinguish the three states a coordination cache can be in.

    Returns "missing" (the producer never ran this session), "offline" (the
    producer ran and FAILED, publishing the None sentinel), or "ready".

    Consumers that write `or {}` / `.get(k, {})` / a bare `if _v:` collapse
    all three into one falsy branch, which renders "checked, found nothing"
    for a check that never executed. That is the failure mode the operating
    posture names as most dangerous: silence a user reads as "checked and
    fine". Use this wherever the falsy branch renders a CONFIDENT negative;
    a cache whose absence merely omits an optional adornment does not need it.
    """
    if key not in st.session_state:
        return "missing"
    return "offline" if st.session_state.get(key) is None else "ready"


def _render_portfolio_not_loaded(show_home_button: bool = True, key_suffix: str = "") -> None:
    """
    Render the shared "holdings not loaded this session" empty state, used by
    any page/section that reads from the `_port_df_enriched` / `_last_port_df`
    / `_last_held_data` session-state caches a Home page visit populates.

    show_home_button=False is for a site rendered from WITHIN Home itself,
    where a "Go to Home" button would be nonsensical — no current call site
    needs this (all of Home's former sub-pages are now standalone), but the
    parameter stays available for a future one.
    """
    st.info(
        "Open the 🏠 Home page once this session to load your holdings — "
        "then this section will populate."
    )
    if show_home_button:
        if st.button("▶ Go to Home", key=f"_pnl_go_home_{key_suffix or 'default'}"):
            st.session_state["_pending_page"] = "🏠 Home"
            st.rerun()


def _portfolio_snapshot_stale() -> bool:
    """
    True when st.session_state.holdings_df — the live source of truth,
    updated in-session by every Trade Journal buy/sell — no longer matches
    the snapshot _port_df_enriched / _last_port_df were built from.

    That snapshot is only rebuilt when the Home page itself runs (the
    build_portfolio_df call). If a trade is logged from another page (e.g.
    Trade Journal) without a Home revisit in between, every downstream
    consumer of _port_df_enriched would otherwise silently keep showing the
    pre-trade share counts/values.
    """
    _hdf = st.session_state.get("holdings_df")
    if _hdf is None or _hdf.empty:
        return False
    _built_sig = st.session_state.get("_holdings_sig_at_home_build")
    if _built_sig is None:
        return False
    _live_sig = frozenset(
        (str(r.get("Ticker") or "").upper(), float(r.get("Shares") or 0))
        for r in _hdf.to_dict("records")
    )
    return _live_sig != _built_sig


def _coord_epoch() -> int:
    """The portfolio generation. Bumped only when the BOOK changes (a logged
    trade), never on a plain rerun — so a cache computed two reruns ago is
    still 'fresh' if no trade happened in between. Freshness here means
    "describes the current book", not "was computed recently"."""
    return int(st.session_state.get("_coord_epoch", 0))


def _stamp_coord(keys=None) -> None:
    """Mark registered coordination caches as describing the CURRENT book.

    Called AFTER a publish block, never before: if an exception intervenes the
    stamp simply does not run, and the key reads absent — the safe direction.
    Under-reporting freshness costs a banner; over-reporting it is exactly the
    confident false negative this mechanism exists to prevent.

    Render-only wiring. The decision — which keys to stamp, and which stamps to
    DROP because their producer published the offline sentinel — lives in the
    pure `coord_freshness.apply_stamps`, where it is unit-tested at its
    boundaries. It was inline here until 2026-08-28, and being inline in
    `app.py` is why the sentinel-stamping bug it now prevents went unnoticed:
    nothing imports this file, so no test could reach the rule.
    """
    st.session_state["_coord_stamps"] = coord_freshness.apply_stamps(
        st.session_state.get("_coord_stamps"),
        # Read the CURRENT value of every key in scope, so a published `None`
        # (a producer that failed) is distinguishable from a real answer.
        {
            k: st.session_state.get(k)
            for k in (coord_freshness.PORTFOLIO_DEPENDENT_KEYS if keys is None else keys)
        },
        keys,
        _coord_epoch(),
    )


def _bump_coord_epoch() -> None:
    """The book changed. Everything derived from it is now a generation behind
    until its producer re-publishes and re-stamps."""
    st.session_state["_coord_epoch"] = _coord_epoch() + 1


def _render_portfolio_stale_banner(key_suffix: str = "") -> None:
    """
    Non-blocking companion to _render_portfolio_not_loaded: holdings HAVE
    been loaded this session, but have since changed (a trade logged
    elsewhere) without a Home revisit to rebuild _port_df_enriched. Warns
    rather than silently showing outdated shares/values — the page still
    renders below with whatever is cached.

    Also covers a second staleness cause (2026-08-04 audit finding): a later
    Home rerun this session hit a data-load failure. Home's own st.stop()
    on that path returns before _port_df_enriched is republished, so it
    keeps serving the pre-outage snapshot with nothing marking it stale —
    _home_data_outage_at flags that case too.
    """
    # A crashed republisher is louder than a stale cache, so it goes first.
    # Rendering this is the point: _refresh_error used to be written and read
    # nowhere, which made a crashed refresh indistinguishable from a successful
    # no-op — the same dead-diagnostic problem already logged against
    # _gate_ledger_save_result / _rec_log_save_result.
    _refresh_err = st.session_state.get("_refresh_error")
    if _refresh_err:
        st.warning(
            f"⚠️ The post-trade refresh did not complete ({_refresh_err}). The "
            "figures below may predate your last trade. Revisit 🏠 Home to rebuild."
        )

    _outage_at = st.session_state.get("_home_data_outage_at")
    if _outage_at:
        st.warning(
            f"⚠️ The last data refresh (at {_outage_at}) failed for one or "
            "more holdings — the figures below may reflect an earlier, "
            "pre-outage snapshot. Revisit 🏠 Home to retry."
        )
        if st.button("🔄 Refresh from Home", key=f"_pnl_outage_refresh_{key_suffix or 'default'}"):
            st.session_state["_pending_page"] = "🏠 Home"
            st.rerun()
        return
    _pd_dropped = getattr(st.session_state.get("_last_port_df"), "attrs", {}).get("dropped_holdings") or []
    if _pd_dropped:
        st.warning(
            f"⚠️ {len(_pd_dropped)} holding(s) skipped — invalid shares or cost basis: "
            + ", ".join(str(d.get("ticker", "?")) for d in _pd_dropped)
            + ". Check the entry for these tickers."
        )

    if not _portfolio_snapshot_stale():
        # Holdings themselves are current — but the caches DERIVED from them
        # may not be. Weakest branch deliberately last: an outage or a changed
        # holdings signature is a bigger claim and should win.
        # Narrowed to the caches THIS surface actually reads (measured per
        # page, not assumed). Without it, 🪞 Trade Review / 📅 Economic Calendar
        # / 🌐 Macro — which read none of these — would warn about dimensions
        # they never display, including a suppression clause that is false on a
        # page showing no suggestions. A banner that fabricates its own scope
        # is the defect class this feature exists to close.
        _nf = coord_freshness.not_fresh_keys(
            st.session_state.get("_coord_stamps"), _coord_epoch(),
            coord_freshness.keys_for_surface(key_suffix),
        )
        _decided = coord_freshness.decide_stale_banner(_nf)
        if _decided:
            _sev, _msg = _decided
            (st.warning if _sev == "warn" else st.caption)(
                ("⚠️ " if _sev == "warn" else "") + _msg
            )
            # Offer the Home jump ONLY when a Home-produced cache is actually
            # stale. Sending the user to Home to clear a 🎯 My Edge or 🧩
            # Intelligence cache changes nothing, and the banner would still be
            # there when they came back — a control that visibly does not work.
            if (_sev == "warn"
                    and "home" in coord_freshness.stale_producers(_nf)
                    and st.button(
                        "🔄 Refresh from Home",
                        key=f"_coord_stale_refresh_{key_suffix or 'default'}")):
                st.session_state["_pending_page"] = "🏠 Home"
                st.rerun()
        return
    st.warning(
        "⚠️ Your holdings changed since this was last loaded (a trade was "
        "logged elsewhere this session) — the figures below may be out of "
        "date. Revisit 🏠 Home to refresh."
    )
    if st.button("🔄 Refresh from Home", key=f"_pnl_stale_refresh_{key_suffix or 'default'}"):
        st.session_state["_pending_page"] = "🏠 Home"
        st.rerun()


def _refresh_portfolio_cache_after_trade(h_df: pd.DataFrame) -> None:
    """
    Rebuild _port_df_enriched/_last_port_df/_holdings_sig_at_home_build right
    after a trade write, mirroring Home's build_portfolio_df call (~app.py:3472)
    so every page reading the cached snapshot reflects the trade immediately
    instead of only after the user happens to revisit Home. Reuses
    _last_held_data for tickers already loaded this session and only fetches
    the tickers newly appearing in holdings (a brand-new BUY) — cheap, unlike
    Home's full held-tickers reload. Best-effort: on any failure this leaves
    the prior cache untouched, and _portfolio_snapshot_stale()'s warning
    banner still catches staleness as a fallback.
    """
    try:
        held_data = dict(st.session_state.get("_last_held_data") or {})
        holdings = h_df.to_dict("records")
        tickers = {str(h.get("Ticker") or "").upper() for h in holdings if h.get("Ticker")}
        missing = [t for t in tickers if t not in held_data]
        if missing:
            for t, bundle in _parallel_load_all(missing).items():
                if bundle is not None:
                    held_data[t] = bundle
        manual_stops = db.load_manual_stops()
        port_df = build_portfolio_df(holdings, held_data, manual_stops=manual_stops)
        port_df = attach_gate_weight(port_df)

        # ── The empty-frame branch, which used to be a single silent skip ────
        # `if not port_df.empty` collapsed two states that mean opposite things:
        #   holdings empty      -> the book genuinely IS $0 (checked, nothing)
        #   holdings non-empty  -> every bundle failed (could not determine)
        # Both left _portfolio_value at its PRE-TRADE value, so selling the last
        # position left a positive, fabricated book size behind. F-261 does not
        # catch it: sizing_unavailable_reason's "portfolio" arm fires on <= 0,
        # and this value is positive and wrong. _portfolio_snapshot_stale() also
        # returns False on an empty holdings frame, so no banner fired either.
        # (F-260 Phase 0, 2026-08-28.)
        _outcome = refresh_outcome(holdings, port_df)
        liquidated = _outcome == "liquidated"
        if _outcome == "outage":
            # Do NOT publish anything derived from a book we failed to measure;
            # flag it so the existing _render_portfolio_stale_banner speaks.
            st.session_state["_home_data_outage_at"] = _now_et().strftime("%I:%M %p")
            st.session_state["_refresh_error"] = (
                f"{len(holdings)} holding(s) could not be priced — cache left "
                "untouched rather than republished from an unmeasured book."
            )
            return

        # Atomic commit: build every value first, then assign in one block. A
        # mid-body exception previously left a HALF-published cache set behind
        # (bare `except: pass`), which is worse than not refreshing at all.
        _sig = frozenset(
            (str(h.get("Ticker") or "").upper(), float(h.get("Shares") or 0))
            for h in holdings
        )
        _basis = gate_basis(port_df)
        _value = 0.0 if liquidated else float(port_df["Market Value"].sum())

        st.session_state["_last_port_df"]      = port_df
        st.session_state["_last_held_data"]    = held_data
        st.session_state["_last_held_tickers"] = sorted(tickers)
        st.session_state["_manual_stops"]      = manual_stops
        st.session_state["_holdings_sig_at_home_build"] = _sig
        st.session_state["_port_df_enriched"]  = port_df
        st.session_state["_acct_gate_cache"]   = _basis
        st.session_state["_portfolio_value"]   = _value
        st.session_state["_refresh_error"]     = None

        # The book changed: every portfolio-DERIVED cache is now a generation
        # behind. Bump first, then stamp only what this function genuinely
        # rebuilt (_acct_gate_cache). The rest keep their older stamp and are
        # reported stale by _render_portfolio_stale_banner — which is the whole
        # point: this function used to write _holdings_sig_at_home_build and
        # thereby SILENCE that banner on 9 pages while risk, correlation and
        # Reduce/Exit still described the pre-trade book.
        _bump_coord_epoch()
        _stamp_coord(["_acct_gate_cache"])
    except Exception as _exc:
        # Recorded rather than swallowed. A bare `pass` made a crashed
        # republisher indistinguishable from a successful no-op — the same
        # dead-diagnostic problem already logged against _gate_ledger_save_result.
        st.session_state["_refresh_error"] = f"{type(_exc).__name__}: {_exc}"


def _fill_news_slot(slot, items: list) -> None:
    """Render curated news items into a sidebar container slot."""
    with slot:
        if not items:
            st.caption("No news found for current holdings.")
            return
        for _ni in items[:10]:
            _clr  = "#00b300" if _ni["label"] == "Positive" else (
                    "#ff4444" if _ni["label"] == "Negative" else "#666")
            _icon = "▲" if _ni["label"] == "Positive" else (
                    "▼" if _ni["label"] == "Negative" else "–")
            _badge = "✅ " if _ni["tier"] == 1 else ""
            _pub   = _ni["publisher"][:18]
            _ago   = _time_ago(_ni["ts"])
            _link  = _safe_link(
                _ni.get("url"),
                _ni.get("title", ""),
                max_len=72,
                style="color:#bbb;text-decoration:none;line-height:1.3",
            )
            st.markdown(
                f"<div style='margin-bottom:7px;padding:5px 7px;"
                f"border-left:3px solid {_clr};"
                f"border-radius:0 4px 4px 0;background:#161616'>"
                f"<div style='font-size:0.72em;color:#666;margin-bottom:2px'>"
                f"<span style='color:{_clr};font-weight:bold'>{_icon}</span> "
                f"<b style='color:#999'>{_ni['ticker']}</b> · "
                f"{_badge}{_pub} · {_ago}</div>"
                f"<div style='font-size:0.78em'>{_link}</div>"
                f"</div>",
                unsafe_allow_html=True,
            )




# ── Password gate ─────────────────────────────────────────────────────────────
def _check_password():
    try:
        expected    = st.secrets.get("app", {}).get("password", "")
        ro_expected = st.secrets.get("app", {}).get("readonly_password", "")
    except Exception:
        expected    = ""
        ro_expected = ""
    # No secrets.toml file on Railway — fall back to flat env vars so the
    # password gate works without mounting a Secret File.
    expected    = expected    or os.environ.get("APP_PASSWORD", "")
    ro_expected = ro_expected or os.environ.get("APP_READONLY_PASSWORD", "")
    if st.session_state.get("auth_ok"):
        return
    if not expected:
        import logging as _logging
        _logging.getLogger(__name__).error("APP_PASSWORD env var not set — app is inaccessible until configured.")
        st.markdown(
            """
            <div style="display:flex;flex-direction:column;align-items:center;
                        justify-content:center;height:70vh;text-align:center;
                        color:#888;font-family:sans-serif;">
              <div style="font-size:5rem;margin-bottom:1rem;">🔌</div>
              <h2 style="color:#ccc;margin:0 0 .5rem;">Down for maintenance</h2>
              <p style="max-width:320px;line-height:1.6;margin:0;">
                We'll be back shortly.<br>Nothing to see here for now.
              </p>
            </div>
            """,
            unsafe_allow_html=True,
        )
        st.stop()
    _render_brand(large=True)
    st.subheader("Sign In")

    _fails = st.session_state.get("_login_fails", 0)
    _locked_until = st.session_state.get("_login_locked_until", 0.0)
    if time.time() < _locked_until:
        remaining = int(_locked_until - time.time())
        st.error(f"Too many failed attempts. Try again in {remaining}s.")
        st.stop()

    pwd = st.text_input("Password", type="password")
    if st.button("Login", type="primary"):
        if hmac.compare_digest(pwd, expected):
            # Owner password — full access; check FIRST so if both passwords are
            # ever set equal, the owner always lands on the owner role.
            st.session_state.auth_ok   = True
            st.session_state["auth_role"] = "owner"
            st.session_state["_login_fails"] = 0
            st.rerun()
        elif ro_expected and hmac.compare_digest(pwd, ro_expected):
            # Read-only password — viewer access.
            st.session_state.auth_ok   = True
            st.session_state["auth_role"] = "viewer"
            st.session_state["_login_fails"] = 0
            st.rerun()
        else:
            _fails += 1
            st.session_state["_login_fails"] = _fails
            if _fails >= 10:
                st.session_state["_login_locked_until"] = time.time() + 300  # 5-min lockout
                st.session_state["_login_fails"] = 0
            elif _fails >= 3:
                time.sleep(2)   # 2s delay after 3rd+ failure
            _quips = [
                "🤔 Hmm. That didn't work.",
                "🙈 Nope, not that one.",
                "🎲 Care to roll the dice again?",
                "🧐 The vibes were off on that one.",
                "🔮 The crystal ball says... try again.",
                "🦆 The duck shook its head.",
                "🚪 Door's still closed.",
                "🌚 The void stared back. Try again.",
            ]
            st.error(_quips[(_fails - 1) % len(_quips)])
    st.stop()

_check_password()


# ── Session state — load from DB once per session ────────────────────────────
if "scanner_results" not in st.session_state:
    st.session_state.scanner_results = None
# One-time hydrate: pull the latest persisted scan (written by the headless cron
# post-open each trading day, or a prior manual full scan) into scanner_results so
# the Home buy-candidate / Grow-Today new-pick lists populate on a COLD load
# WITHOUT the user running the ~20s scanner. Best-effort, once per session (the
# flag prevents a DB read every rerun); a manual scan still overrides + re-persists.
# Inert (no-op) until the scanner_cache table exists → behaves exactly as today.
if (st.session_state.scanner_results is None
        and not st.session_state.get("_scanner_cache_checked")):
    st.session_state["_scanner_cache_checked"] = True
    try:
        _persisted_scan = db.load_scanner_cache()
    except Exception:
        _persisted_scan = None
    if (_persisted_scan and _persisted_scan.get("df") is not None
            and not _persisted_scan["df"].empty):
        st.session_state.scanner_results = _persisted_scan["df"]
        st.session_state["_scanner_results_meta"] = {
            "scan_date":  _persisted_scan.get("scan_date"),
            "source":     _persisted_scan.get("source"),
            "scanned_at": _persisted_scan.get("scanned_at"),
        }
        # Invalidate the Home synthesis cache so the Brief rebuilds against the
        # hydrated scanner results (same signal a manual scan raises).
        st.session_state["_scanner_ver"] = st.session_state.get("_scanner_ver", 0) + 1
if "last_refresh" not in st.session_state:
    st.session_state.last_refresh = _now_et()
if "nav_page" not in st.session_state:
    st.session_state.nav_page = "🏠 Home"
# Apply any pending navigation set by mid-page buttons (must run before
# the sidebar radio widget renders so the widget picks up the new value).
if "_pending_page" in st.session_state:
    _dest = st.session_state.pop("_pending_page")
    if _dest == "📈 Analysis":
        # Remember where we came from so a Back button can return us there
        st.session_state["_nav_origin"] = st.session_state.get("nav_page", "")
    st.session_state["nav_page"] = _dest
# ── Initial DB load, with an honest failure path ─────────────────────────────
# Until 2026-08-17 this latched `db_loaded = True` UNCONDITIONALLY after three
# LENIENT loaders that return empty containers on failure. So a failed first
# load showed an empty portfolio, an empty trade journal and a FABRICATED
# default watchlist — with no banner and no retry — for the rest of the session,
# even after Supabase recovered. The user hit exactly this during the 2026-08-15
# Railway cutover (wrong RLS key → "app shows no data").
#
# The strict `_or_none` loaders distinguish "read fine, genuinely empty" from
# "could not read". `db_loaded` now means ONLY "the initial load succeeded";
# `_db_load_failure` carries the fault and drives the banner further down (after
# the sidebar renders, so nav survives — see the outage gate below).
#
# holdings is the HARD gate (every decision depends on it, and it's the probe
# db.unavailable_detail() uses); watchlist/trades failing alone is a SOFT
# warning, because the book itself is still correct.
if not st.session_state.get("db_loaded"):
    # Explicit `is None`, not `... or {}` — check_antipatterns.py flags the
    # collapse, and rightly: this key IS the offline record, so folding a
    # falsy-but-present value into "no failure" is the exact class.
    _fail_rec  = st.session_state.get("_db_load_failure")
    _prev_fail = _fail_rec.get("at") if _fail_rec is not None else None
    _may_retry = (st.session_state.pop("_db_retry_requested", False)
                  or db.should_attempt_db_reload(_prev_fail, time.time()))
    if _may_retry:
        _h = db.load_holdings_or_none()
        # w/t are only attempted when holdings succeeded — same as before this
        # extraction: no point reading them if the book itself is unreadable,
        # and classify_load_result's "holdings" branch doesn't consult them.
        _w = db.load_watchlist_or_none() if _h is not None else None
        _t = db.load_trades_or_none() if _h is not None else None
        if _h is None:
            # Keep the containers a valid TYPE (many call sites do .iterrows());
            # the protection is the hard stop below, not a sentinel smuggled
            # into a widely-read frame.
            st.session_state.holdings_df = pd.DataFrame(columns=db._HOLDINGS_COLS)
            st.session_state.watchlist   = []
            st.session_state.trades_df   = pd.DataFrame(columns=db._TRADE_COLS)
        else:
            st.session_state.holdings_df = _h
            # NEVER fall back to _DEFAULT_WATCHLIST here: showing a watchlist the
            # user never created, as theirs, is a wrong ASSERTION — worse than a
            # wrong absence.
            st.session_state.watchlist = _w if _w is not None else []
            st.session_state.trades_df = _t if _t is not None else pd.DataFrame(columns=db._TRADE_COLS)
        _fail = db.classify_load_result(_h, _w, _t, time.time())
        if _fail is not None:
            st.session_state["_db_load_failure"] = _fail
        else:
            st.session_state.pop("_db_load_failure", None)
            st.session_state.db_loaded = True

# ── Read-only viewer mode ────────────────────────────────────────────────────
# PRIMARY: login password role (auth_role="owner" → full access,
# auth_role="viewer" → read-only). Set by _check_password() when the
# optional readonly_password is configured in st.secrets["app"].
# FALLBACK: when no password role is set (gate disabled / future email-auth
# deployment), falls back to the owner-email allowlist. Fails OPEN to full
# access when unconfigured or the viewer email can't be determined — bounded
# because this is a PRIVATE Streamlit deployment. Real enforcement is
# db.set_readonly() (every user-data write no-ops); the UI disabled= flags
# are UX on top of that backstop.
def _viewer_email() -> str:
    try:
        _u = getattr(st, "user", None)
        if _u is None:
            _u = getattr(st, "experimental_user", None)
        if _u is not None:
            _em = getattr(_u, "email", None)
            if _em is None and hasattr(_u, "get"):
                _em = _u.get("email")
            return str(_em or "").strip().lower()
    except Exception:
        pass
    return ""

try:
    _owner_raw = st.secrets.get("owner_emails", [])
except Exception:
    _owner_raw = []
if isinstance(_owner_raw, str):
    _owner_emails = [e.strip().lower() for e in _owner_raw.split(",") if e.strip()]
else:
    _owner_emails = [str(e).strip().lower() for e in (_owner_raw or [])]
_viewer_em  = _viewer_email()
_auth_role  = st.session_state.get("auth_role")
if _auth_role == "viewer":
    _readonly_viewer = True          # logged in with the read-only password
elif _auth_role == "owner":
    _readonly_viewer = False         # logged in with the owner password — full access
else:
    # No password role (gate disabled / email-auth deployment) — fall back to the
    # owner-email allowlist; fails OPEN to full access when unconfigured/unknown.
    _readonly_viewer = bool(_owner_emails) and bool(_viewer_em) and (_viewer_em not in _owner_emails)
st.session_state["_readonly"] = _readonly_viewer
db.set_readonly(_readonly_viewer)

# ── Refresh cooldown helpers (Phase 1 rate-limit resilience) ────────────────
# MUST be defined before the sidebar block below — the refresh buttons there
# call these at module-execution time, and Python resolves names top-to-bottom,
# so a later definition would NameError on first run.
def _refresh_gate(bucket: str) -> tuple[bool, int]:
    """Cooldown gate shared by the heavy refresh buttons (Phase 1 rate-limit
    resilience). Returns (locked, seconds_remaining). Buttons sharing a `bucket`
    lock together — they all clear the cache and re-fetch across the same price
    providers, so one press should cool down the others too. Call
    `_refresh_gate_arm(bucket)` the instant a refresh fires.
    The displayed countdown may be stale between reruns, but the lock is
    recomputed from the timestamp on every render, so it always lifts correctly
    once REFRESH_COOLDOWN_SEC has elapsed."""
    armed = st.session_state.get(f"_refresh_armed_{bucket}")
    if armed is None:
        return (False, 0)
    remaining = int(REFRESH_COOLDOWN_SEC - (time.time() - armed))
    return (remaining > 0, max(remaining, 0))


def _refresh_gate_arm(bucket: str) -> None:
    st.session_state[f"_refresh_armed_{bucket}"] = time.time()


