    _cur_page = st.session_state.get("nav_page", "🏠 Home")
    _risk_alerts_raw  = st.session_state.get("_risk_high_alerts_cache")
    _cw_alerts        = 0 if _risk_alerts_raw is None else len(_risk_alerts_raw)
