            ("Health",    "🏆 Health",     ":material/analytics:"),
            ("My Edge",             "🎯 My Edge",              ":material/trophy:"),
            ("Risk Analysis",   "🔗 Risk Analysis",           ":material/monitoring:"),
            ("Intelligence", "🧩 Intelligence", ":material/hub:"),
