@st.cache_data(ttl=3600, show_spinner=False)
def _cached_sentiment(ticker_csv: str) -> dict[str, dict]:
    """Fetch Finnhub news sentiment for a sorted comma-joined ticker CSV.

    ticker_csv serves as the cache key (same tickers = same cache entry).
    Returns {ticker: sentiment_dict}; empty dict when Finnhub is not configured.
    """
    from stock_analyzer.news_sentiment import fetch_sentiment_for_tickers
    tickers = [t for t in ticker_csv.split(",") if t]
    return fetch_sentiment_for_tickers(tickers)


@st.cache_data(ttl=3600, show_spinner=False)
def _cached_analyst_coverage_recent() -> dict:
    """Newest analyst_coverage row per ticker within ANALYST_COVERAGE_FRESH_DAYS.
    Returns {TICKER: {consensus_rating, avg_pt, n_firms, article_date}}; empty dict
    when none/offline. Awareness-only — used to ANNOTATE cards, never to gate/rank."""
    from stock_analyzer import db as _acr_db
    from stock_analyzer.constants import ANALYST_COVERAGE_FRESH_DAYS
    import json as _acr_json
    df = _acr_db.load_analyst_coverage(days=ANALYST_COVERAGE_FRESH_DAYS)
    out: dict = {}
    if df is None or df.empty:
        return out
    for _, _row in df.iterrows():   # DataFrame is newest-first; keep first row per ticker
        _t = str(_row.get("ticker", "")).upper()
        if not _t or _t in out:
            continue
        _analysts = _row.get("analysts")
        if isinstance(_analysts, str):
            try:
                _analysts = _acr_json.loads(_analysts)
            except Exception:
                _analysts = []
        out[_t] = {
            "consensus_rating": _row.get("consensus_rating"),
            "avg_pt":           _row.get("avg_pt"),
            "n_firms":          len(_analysts or []),
            "article_date":     str(_row.get("article_date")),
        }
    return out


# ── Signal-flow Sankey (shared) ──────────────────────────────────────────────
# Builds the New-Positions → acted/missed → win/loss/flat Sankey figure from a
# recommendations_history.signal_flow() dict. Shared by the Recommendations
# History page and the AI Insights monthly report so the two can never drift.
# Returns a go.Figure, or None when there's nothing to draw.
def _signal_flow_sankey(flow: dict, title: str):
    _labels = [
        "New Positions Surfaced",
        "Acted",        "Not acted",
        "Win (acted)",  "Loss (acted)",  "Flat / Open (acted)",
        "Rose (missed)", "Fell — dodged", "Flat / Open (missed)",
    ]
    _ncolor = [
        "#60a5fa",
        "#34d399", "#94a3b8",
        "#22c55e", "#ef4444", "#64748b",
        "#4ade80", "#f87171", "#475569",
    ]
    _src = [0, 0, 1, 1, 1, 2, 2, 2]
    _tgt = [1, 2, 3, 4, 5, 6, 7, 8]
    _val = [
        flow["n_acted"],    flow["n_missed"],
        flow["acted_win"],  flow["acted_loss"],  flow["acted_flat"],
        flow["missed_win"], flow["missed_loss"], flow["missed_flat"],
    ]
    _lc = [
        "rgba(99,179,237,0.45)",  "rgba(148,163,184,0.3)",
        "rgba(134,239,172,0.45)", "rgba(252,165,165,0.45)", "rgba(100,116,139,0.3)",
        "rgba(134,239,172,0.3)",  "rgba(248,113,113,0.3)",  "rgba(71,85,105,0.2)",
    ]
    _pairs = [(s, t, v, c) for s, t, v, c in zip(_src, _tgt, _val, _lc) if v > 0]
    if not _pairs:
        return None
    _s, _t, _v, _c = zip(*_pairs)
    _fig = go.Figure(go.Sankey(
        arrangement="snap",
        node=dict(label=_labels, color=_ncolor, pad=22, thickness=18,
                  line=dict(color="rgba(255,255,255,0.08)", width=0.5)),
        link=dict(source=list(_s), target=list(_t), value=list(_v), color=list(_c)),
    ))
    _fig.update_layout(
        height=360, margin=dict(l=0, r=0, t=36, b=8), template="plotly_dark",
        paper_bgcolor="rgba(0,0,0,0)", font=dict(size=11, color="#cbd5e1"),
        title=dict(text=title, font=dict(size=13), x=0),
    )
    return _fig


