            # Action buttons
            _qr_bc1, _qr_bc2 = st.columns([3, 1])
            with _qr_bc1:
                if st.button(f"▶ Analyze {_qr_res['ticker']}", key="_qr_full_btn"):
                    st.session_state["_pending_page"]    = "📈 Analysis"
                    st.session_state["_analysis_ticker"] = _qr_res["ticker"]
