                                    _aicon = _post_action_icons.get(_act, "—")
                                    _imp   = _pp["dollar_impact"]
                                    _mc    = "#00C851" if _imp >= 0 else "#ef4444"
                                    _smc   = "#00C851" if _pp["sector_move"] >= 0 else "#ef4444"
                                    # Display-only label, Title Case for every action so
